import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"VersionsPanel","description":"","frontmatter":{},"headers":[],"relativePath":"workbench/versions-panel.md","filePath":"workbench/versions-panel.md"}'),r={name:"workbench/versions-panel.md"};function n(d,e,i,h,c,l){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="versionspanel" tabindex="-1">VersionsPanel <a class="header-anchor" href="#versionspanel" aria-label="Permalink to &quot;VersionsPanel&quot;">​</a></h1><p>VersionsPanel is the list of the saved versions of a document, with the actions to look at one and to restore it.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for the history of a document. The application passes the versions, newest first, with the time and the author already written for the reader, and keeps which one is shown: <code>onpreview</code> asks to show a version, and the application passes its id back in <code>current</code>. Restoring is the application&#39;s too; confirm it first if it cannot be undone.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>versions</code></td><td>required</td><td>The versions, newest first, <code>VersionEntry[]</code></td></tr><tr><td><code>current</code></td><td></td><td>The id of the version shown</td></tr><tr><td><code>onpreview</code></td><td></td><td>Called with the id of the version that is pressed</td></tr><tr><td><code>onrestore</code></td><td></td><td>Called with the id of the past version shown</td></tr><tr><td><code>title</code></td><td><code>versions</code> message</td><td>The title in the head</td></tr><tr><td><code>empty</code></td><td><code>noVersions</code> message</td><td>What shows when there is no version</td></tr><tr><td><code>onclose</code></td><td></td><td>Shows a close button in the head</td></tr><tr><td><code>side</code></td><td><code>panel</code></td><td>The width, as <a href="./../components/panel">Panel</a>&#39;s <code>side</code></td></tr></tbody></table><p>A <code>VersionEntry</code> is <code>{ id, label, when, by }</code>, all strings.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>A <a href="./../components/panel">Panel</a> with a <a href="./../components/toolbar">Toolbar</a> as its head and a <a href="./../components/list">List</a> of two-line items: the name, then when and by whom, one line each with an ellipsis. The current version is selected. The first version is the latest; while another one is current, a <a href="./../components/footer">Footer</a> holds two actions, back to the latest (the <code>backToLatest</code> message; it calls <code>onpreview</code> with the latest id) and restore (the <code>restore</code> message, the primary action).</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/versions-panel/" title="VersionsPanel" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/versions-panel/" target="_blank" rel="noopener">VersionsPanel</a></figcaption></figure>',11)])])}const m=t(r,[["render",n]]);export{f as __pageData,m as default};
